void List_Spite_Attribute_release(List_Spite_Attribute* self) {
if (self == 0) return;
self->header.ref_count = self->header.ref_count - 1;
if (self->header.ref_count > 0) return;
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { Spite_Attribute_release(self->items[spite_index]); }
SPITE_FREE(self->items);
SPITE_FREE(self);
}
void List_Spite_Attribute_add(List_Spite_Attribute* self, Spite_Attribute* value) {
if (self->count == self->capacity) {
int64_t new_capacity = self->capacity == 0 ? 4 : self->capacity * 2;
self->items = (Spite_Attribute**)SPITE_REALLOC(self->items, (size_t)new_capacity * sizeof(Spite_Attribute*));
self->capacity = new_capacity;
}
self->items[self->count] = value;
self->count = self->count + 1;
}
int64_t List_Spite_Attribute_count(List_Spite_Attribute* self) {
return self->count;
}
Spite_Attribute* List_Spite_Attribute_get(List_Spite_Attribute* self, int64_t index) {
if (index < 0 || index >= self->count) {
return Spite_Attribute_default();
}
return Spite_Attribute_retain(self->items[index]);
}
Spite_Attribute* List_Spite_Attribute_at(List_Spite_Attribute* self, int64_t index) {
if (index < 0 || index >= self->count) return 0;
return Spite_Attribute_retain(self->items[index]);
}
void List_Spite_Attribute_set(List_Spite_Attribute* self, int64_t index, Spite_Attribute* value) {
if (index < 0 || index >= self->count) { Spite_Attribute_release(value); return; }
Spite_Attribute_release(self->items[index]);
self->items[index] = value;
}
void List_Spite_Attribute_insert(List_Spite_Attribute* self, int64_t index, Spite_Attribute* value) {
int64_t clamped_index = index < 0 ? 0 : (index > self->count ? self->count : index);
if (self->count == self->capacity) {
int64_t new_capacity = self->capacity == 0 ? 4 : self->capacity * 2;
self->items = (Spite_Attribute**)SPITE_REALLOC(self->items, (size_t)new_capacity * sizeof(Spite_Attribute*));
self->capacity = new_capacity;
}
for (int64_t spite_index = self->count; spite_index > clamped_index; spite_index = spite_index - 1) { self->items[spite_index] = self->items[spite_index - 1]; }
self->items[clamped_index] = value;
self->count = self->count + 1;
}
void List_Spite_Attribute_prepend(List_Spite_Attribute* self, Spite_Attribute* value) {
List_Spite_Attribute_insert(self, 0, value);
}
void List_Spite_Attribute_remove_at(List_Spite_Attribute* self, int64_t index) {
if (index < 0 || index >= self->count) return;
Spite_Attribute_release(self->items[index]);
for (int64_t spite_index = index; spite_index < self->count - 1; spite_index = spite_index + 1) { self->items[spite_index] = self->items[spite_index + 1]; }
self->count = self->count - 1;
}
Spite_Attribute* List_Spite_Attribute_pop(List_Spite_Attribute* self) {
if (self->count == 0) return Spite_Attribute_default();
Spite_Attribute* value = self->items[self->count - 1];
self->count = self->count - 1;
return value;
}
Spite_Attribute* List_Spite_Attribute_remove_first(List_Spite_Attribute* self) {
if (self->count == 0) return Spite_Attribute_default();
Spite_Attribute* value = self->items[0];
int64_t index = 0;
for (int64_t spite_index = index; spite_index < self->count - 1; spite_index = spite_index + 1) { self->items[spite_index] = self->items[spite_index + 1]; }
self->count = self->count - 1;
return value;
}
Spite_Attribute* List_Spite_Attribute_first(List_Spite_Attribute* self) {
if (self->count == 0) return Spite_Attribute_default();
return Spite_Attribute_retain(self->items[0]);
}
Spite_Attribute* List_Spite_Attribute_last(List_Spite_Attribute* self) {
if (self->count == 0) return Spite_Attribute_default();
return Spite_Attribute_retain(self->items[self->count - 1]);
}
bool List_Spite_Attribute_is_empty(List_Spite_Attribute* self) {
return self->count == 0;
}
void List_Spite_Attribute_clear(List_Spite_Attribute* self) {
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { Spite_Attribute_release(self->items[spite_index]); }
self->count = 0;
}
void List_Spite_Attribute_reverse(List_Spite_Attribute* self) {
for (int64_t spite_index = 0; spite_index < self->count / 2; spite_index = spite_index + 1) {
Spite_Attribute* spite_swap_temporary = self->items[spite_index];
self->items[spite_index] = self->items[self->count - 1 - spite_index];
self->items[self->count - 1 - spite_index] = spite_swap_temporary;
}
}
